fn reply_connection_or_error(reply: u64, connection: u64, generation: i64) {
    let status = unsafe {
        ipc_reply_connection(reply, connection, IpcRights::SEND | IpcRights::CALL, generation)
    };
    if status != 0 {
        // A registration without MINT_CONNECTION cannot be handed to a
        // lookup caller. Do not strand the retained reply token: report a
        // protocol error so the caller can discard/retry it.
        unsafe {
            ipc_reply(reply, ns::ERR_INVALID);
        }
    }

///
/// Both endpoint caps and connection caps qualify, provided they carry
/// `MINT_CONNECTION`. Connection caps allow re-delegation with rights
/// attenuation: the minted rights are the intersection of the requested
/// rights and the source cap's rights.
fn mintable_endpoint(
    ipc: &IpcRegistry,
    asid: AddressSpaceId,
    cap: CapabilityId,
    requested: ConnectionRights,
) -> Result<(EndpointId, ConnectionRights), IpcError> {
    let (endpoint, source_rights) = match ipc.cap(asid, cap)? {
        Capability::Endpoint {
            endpoint,
            rights,
        }
        | Capability::Connection {
            endpoint,
            rights,
        } => (endpoint, rights),
        _ => return Err(IpcError::WrongType),
    };
    if !source_rights.contains(ConnectionRights::MINT_CONNECTION) {
        return Err(IpcError::PermissionDenied);
    }
    if ipc.endpoints.get(&endpoint).is_some_and(|endpoint| endpoint.closing) {
        return Err(IpcError::Pending);
    }
    Ok((endpoint, requested.intersection(source_rights)))

    /// Reply with an attenuated connection minted from a re-delegable
    /// connection. This is the mediation counterpart to `reply_connection`:
    /// a controller need not own the target service's endpoint.
    pub fn reply_connection_ref(
        mut self,
        connection: ConnectionRef<'_>,
        rights: IpcRights,
        result: i64,
    ) -> Result<(), IpcError> {
        let reply = self.cap.take().expect("reply token already consumed");
        let status = kernel::ipc_reply_connection(reply, connection.cap, rights, result);
        if status == catten_syscall::ipc_status::OK {
            Ok(())
        } else {
            let _ = kernel::ipc_close(reply);
            Err(IpcError::Status(status))
        }
    }
}
